'use strict';

const assert=require('assert');
const core=require('../../system-master/book-system/canonical-parent-v2-f6-core.js');
const gate=require('../../system-master/book-system/workflow-evidence-parent-gate-v2.js');
const H=v=>core.sha256(String(v));
function clone(v){return JSON.parse(JSON.stringify(v));}
function expectCode(code,fn){assert.throws(fn,e=>e&&e.code===code,`expected ${code}`);}
function parentAt(status='REVISING'){
  return core.sealParent({schema_version:core.SCHEMA_VERSION,state_version:10,state_digest:'0'.repeat(64),book_project:{book_project_id:'BOOK-PROJECT-001',book_id:'BOOK-001',status},governed_objects:{governing_briefs:[{object_id:'BRIEF-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('BRIEF')}],canon_manifests:[{object_id:'CANON-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('CANON')}],story_bibles:[{object_id:'BIBLE-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('BIBLE')}],book_plans:[{object_id:'PLAN-1',version:'1',book_project_id:'BOOK-PROJECT-001',object_digest:H('PLAN')}],manuscripts:[{object_id:'MS-1',version:'1',book_project_id:'BOOK-PROJECT-001',artifact_digest:H('MS')} ]},research_evidence_links:[],author_decisions:[],integration_proposals:[],rights_custody_records:[],style_profiles:[{object_id:'STYLE-1',version:'1',book_project_id:'BOOK-PROJECT-001',standing:'CURRENT',profile_digest:H('STYLE')}],export_releases:[],active:{governing_brief_ref:'BRIEF-1:1',canon_manifest_ref:'CANON-1:1',story_bible_ref:'BIBLE-1:1',book_plan_ref:'PLAN-1:1',canonical_manuscript_ref:'MS-1:1',style_profile_ref:'STYLE-1:1'},authority_metadata:{owner:'SYSTEM_MASTER/BOOK'},mutation_head:null});
}
function workflowReceipt(){return{receipt_id:'WF-EVID-F10-001',receipt_digest:H('WF-EVID-F10-001'),canonical_effect_allowed:false,output_refs:['OUT-1'],evidence_refs:['EV-1']};}
function externalEvidence(overrides={}){return Object.assign({evidence_ref:'EXT-EVID-F10-001',result_digest:H('RESULT'),source_identity:{object_id:'MS-1',object_version:'1',object_digest:H('MS')},provider_identity:{service_id:'DOCUMENT_SERVICE',operation_id:'RENDER_OR_VALIDATE',provider_subject_sha:H('PROVIDER-SUBJECT'),implementation_or_artifact_id:'IMPL-F10-001'}},overrides);}
function bind(parent,evidenceClass,evidence,extra={}){return gate.bindEvidenceToFreshParent(Object.assign({canonical_parent:parent,expected_parent_state_version:parent.state_version,expected_parent_state_digest:parent.state_digest,evidence_class:evidenceClass,evidence},extra));}
function systemEffect(parent,type,payload={record:{id:'X'}}){return{effect_schema_version:core.EFFECT_SCHEMA_VERSION,effect_request_id:'F10-EFFECT-001',idempotency_key:'F10-IDEM-001',actor_class:'SYSTEM',authority_ref:'SYSTEM-AUTHORITY-FIXTURE',expected_parent_state_version:parent.state_version,expected_parent_state_digest:parent.state_digest,effect_type:type,effect_payload:payload,effect_payload_digest:core.effectPayloadDigest(payload),subject_identity_refs:['SUBJECT-F10'],evidence_refs:['EVID-F10'],specialist_receipt_refs:['SPECIALIST-F10'],created_at:'2026-09-12T07:50:00.000Z',expected_specialist_ledger_identity:H('SPECIALIST')};}
const tests=[];function t(id,name,fn){tests.push({id,name,fn});}

t('Q064','workflow evidence/provenance remains evidence-only and cannot assert canonical effects',()=>{const p=parentAt(),r=workflowReceipt(),b=bind(p,'WORKFLOW_RECEIPT',r);assert.strictEqual(b.canonical_effect_allowed,false);assert.strictEqual(b.requires_fresh_parent_reread_before_typed_effect,true);const bad=clone(r);bad.canonical_effect_allowed=true;expectCode('EVIDENCE_AUTHORITY_ASSERTION_FORBIDDEN',()=>bind(p,'WORKFLOW_RECEIPT',bad));const pub=clone(r);pub.publication_authorized=true;expectCode('EVIDENCE_AUTHORITY_ASSERTION_FORBIDDEN',()=>bind(p,'WORKFLOW_RECEIPT',pub));});

t('Q066','external/native evidence must bind a freshly re-read exact parent before later typed effect use',()=>{const p=parentAt(),e=externalEvidence(),b=bind(p,'EXTERNAL_PROVIDER_RESULT',e,{expected_source_identity:e.source_identity,expected_provider_identity:e.provider_identity});assert.strictEqual(gate.validateBindingAgainstFreshParent(b,p),true);const advanced=core.applyEffect(p,systemEffect(p,'ADVANCE_PROJECT_STATUS',{to_status:'EXPORT_FROZEN'})).parent_state;expectCode('FRESH_PARENT_REREAD_REQUIRED',()=>gate.validateBindingAgainstFreshParent(b,advanced));});

t('Q085','canonical parent history rejects raw manuscript content fields',()=>{const p=parentAt();p.author_decisions.push({decision_id:'D-RAW',status:'APPROVED',manuscript_text:'forbidden raw text'});const sealed=core.sealParent(p);assert.throws(()=>core.validateParent(sealed),e=>e&&e.code==='FORBIDDEN_PRIVATE_FIELD');});

t('Q086','rights/custody canonical effect rejects raw private source bytes',()=>{const p=parentAt();const record={rights_record_id:'R-F10',record_version:1,book_project_id:'BOOK-PROJECT-001',source_ref:'SRC',evidence_issuer_ref:'ISSUER',evidence_ref:'EVID',intended_use_scope:'DECLARED',disposition:'ACCEPTED_FOR_DECLARED_SCOPE',source_bytes:'private bytes'};const effect=systemEffect(p,'REGISTER_RIGHTS_CUSTODY_RECORD',{record});effect.effect_payload_digest=core.effectPayloadDigest(effect.effect_payload);assert.throws(()=>core.applyEffect(p,effect),e=>e&&e.code==='FORBIDDEN_PRIVATE_FIELD');});

t('Q087','provider/native receipt exact source or provider identity mismatch is rejected',()=>{const p=parentAt(),e=externalEvidence(),wrong=clone(e.source_identity);wrong.object_digest='a'.repeat(64);expectCode('EXTERNAL_EVIDENCE_SOURCE_IDENTITY_MISMATCH',()=>bind(p,'EXTERNAL_PROVIDER_RESULT',e,{expected_source_identity:wrong,expected_provider_identity:e.provider_identity}));const wp=clone(e.provider_identity);wp.provider_subject_sha='b'.repeat(64);expectCode('EXTERNAL_EVIDENCE_PROVIDER_IDENTITY_MISMATCH',()=>bind(p,'EXTERNAL_PROVIDER_RESULT',e,{expected_source_identity:e.source_identity,expected_provider_identity:wp}));});

t('Q088','normalized semantic output never implies native fidelity',()=>{const p=parentAt(),e=externalEvidence({semantic_output_digest:H('SEMANTIC'),native_fidelity_verified:false}),b=bind(p,'EXTERNAL_PROVIDER_RESULT',e,{expected_source_identity:e.source_identity,expected_provider_identity:e.provider_identity});assert.strictEqual(b.native_fidelity_verified,false);const bad=clone(e);bad.native_fidelity_verified=true;expectCode('NATIVE_FIDELITY_CANNOT_BE_INFERRED',()=>bind(p,'EXTERNAL_PROVIDER_RESULT',bad,{expected_source_identity:bad.source_identity,expected_provider_identity:bad.provider_identity}));});

t('Q089','export PASS remains publication-not-authorized',()=>{const p=parentAt(),record={release_id:'REL-F10',digest:H('REL'),format:'PDF',publication_authority_state:'NOT_AUTHORIZED',publication_authorized:false};const effect=systemEffect(p,'REGISTER_EXPORT_RELEASE',{record});effect.effect_payload_digest=core.effectPayloadDigest(effect.effect_payload);const next=core.applyEffect(p,effect).parent_state;assert.strictEqual(next.export_releases[0].publication_authorized,false);assert.strictEqual(next.export_releases[0].publication_authority_state,'NOT_AUTHORIZED');});

t('Q090','publication authority expiration or revocation cannot bypass the build-blocked publication effect',()=>{const p=parentAt(),record={authorization_id:'PUB-F10',status:'REVOKED',expires_at:'2026-09-11T00:00:00Z'};const effect=systemEffect(p,'REGISTER_PUBLICATION_AUTHORIZATION',{record});effect.effect_payload_digest=core.effectPayloadDigest(effect.effect_payload);assert.throws(()=>core.applyEffect(p,effect),e=>e&&e.code==='PUBLICATION_EFFECT_BUILD_BLOCKED');});

t('F10-WORKFLOW-REPLAY','recovered replay verification is evidence-only and cannot perform provider or canonical execution',()=>{const p=parentAt(),replay={replay_verified:true,receipt_count:3,terminal_receipt_digest:H('TERM'),provider_execution_performed:false,canonical_effect_performed:false};const b=bind(p,'WORKFLOW_REPLAY_VERIFICATION',replay);assert.strictEqual(b.canonical_effect_allowed,false);assert.strictEqual(b.publication_authorized,false);});

t('F10-NATIVE-EXPLICIT','native fidelity class requires explicit exact native validation evidence',()=>{const p=parentAt(),e=externalEvidence({native_fidelity_verified:true,native_validation_evidence_ref:'NATIVE-VALIDATION-FIXTURE-REF',native_validation_result_digest:H('NATIVE-RESULT')});const b=bind(p,'NATIVE_FIDELITY_VERIFIED',e,{expected_source_identity:e.source_identity,expected_provider_identity:e.provider_identity});assert.strictEqual(b.native_fidelity_verified,true);const bad=clone(e);delete bad.native_validation_evidence_ref;expectCode('NATIVE_FIDELITY_EVIDENCE_REQUIRED',()=>bind(p,'NATIVE_FIDELITY_VERIFIED',bad,{expected_source_identity:bad.source_identity,expected_provider_identity:bad.provider_identity}));});

let passed=0;for(const q of tests){try{q.fn();passed++;console.log(`PASS ${q.id} ${q.name}`);}catch(e){console.error(`FAIL ${q.id} ${q.name}`);console.error(e&&e.stack||e);process.exitCode=1;}}if(passed!==tests.length)process.exit(1);console.log(JSON.stringify({qualification_id:'BOOK-RECONSTRUCTION-B00-F10-EVIDENCE-RECOVERY-SEAM-001',result_class:'PASS',case_count:tests.length,pass_count:passed,fail_count:0},null,2));
